// =============================================================================
// percussion_player.sv
// -----------------------------------------------------------------------------
// One-shot percussion player for kick, snare and hi-hat.
//
// Instrument IDs (instrument_t enum):
//   SNARE = 1,  KICK = 2,  HIHAT = 3
//
// LUT values stored as unsigned 24-bit hex (two's complement).
// Vivado requires this format in initial blocks - signed decimal literals
// with a leading minus sign are not supported in synthesis.
//
// Durations at 48 kHz:
//   Kick  : 3840 samples (80 ms)
//   Snare : 2880 samples (60 ms)
//   Hi-hat: 1440 samples (30 ms)
// =============================================================================

module percussion_player (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        sample_en,
    input  logic        in_valid,
    input  logic [7:0]  synth_id,
    output logic signed [23:0] out_sample
);

    localparam logic [7:0] ID_SNARE = 8'd1;
    localparam logic [7:0] ID_KICK  = 8'd2;
    localparam logic [7:0] ID_HIHAT = 8'd3;

    localparam int KICK_LEN  = 3840;
    localparam int SNARE_LEN = 2880;
    localparam int HIHAT_LEN = 1440;

    // LUTs as unsigned hex - interpreted as signed via $signed() on readout
    logic [23:0] kick_lut  [0:KICK_LEN-1];
    logic [23:0] snare_lut [0:SNARE_LEN-1];
    logic [23:0] hihat_lut [0:HIHAT_LEN-1];

