        hihat_lut[1405] = 24'h00C518;
        hihat_lut[1406] = 24'h000630;
        hihat_lut[1407] = 24'hFEA705;
        hihat_lut[1408] = 24'hFE2981;
        hihat_lut[1409] = 24'hFAEE5D;
        hihat_lut[1410] = 24'hFAAE51;
        hihat_lut[1411] = 24'hFD99E7;
        hihat_lut[1412] = 24'h0AE71E;
        hihat_lut[1413] = 24'h0C31FC;
        hihat_lut[1414] = 24'hF5D8AF;
        hihat_lut[1415] = 24'hF06547;
        hihat_lut[1416] = 24'h040F54;
        hihat_lut[1417] = 24'h0F92C6;
        hihat_lut[1418] = 24'h0629A1;
        hihat_lut[1419] = 24'hF2E793;
        hihat_lut[1420] = 24'hF6B43C;
        hihat_lut[1421] = 24'h01CA6B;
        hihat_lut[1422] = 24'h0A4DE6;
        hihat_lut[1423] = 24'h04B4AE;
        hihat_lut[1424] = 24'hFC5FC9;
        hihat_lut[1425] = 24'hFCDDB6;
        hihat_lut[1426] = 24'hFA376B;
        hihat_lut[1427] = 24'hF8975F;
        hihat_lut[1428] = 24'h0340E0;
        hihat_lut[1429] = 24'h04101C;
        hihat_lut[1430] = 24'hFE4B2B;
        hihat_lut[1431] = 24'hFF60CD;
        hihat_lut[1432] = 24'h0243EA;
        hihat_lut[1433] = 24'hF98213;
        hihat_lut[1434] = 24'hF79444;
        hihat_lut[1435] = 24'hFCAF35;
        hihat_lut[1436] = 24'h0C5DC1;
        hihat_lut[1437] = 24'h0C0702;
        hihat_lut[1438] = 24'hF5B0AA;
        hihat_lut[1439] = 24'hEDFACE;
    end

    logic [$clog2(KICK_LEN)-1:0]  kick_ptr;
    logic [$clog2(SNARE_LEN)-1:0] snare_ptr;
    logic [$clog2(HIHAT_LEN)-1:0] hihat_ptr;

    logic kick_active, snare_active, hihat_active;

    logic trig_kick, trig_snare, trig_hihat;
    assign trig_kick  = in_valid && (synth_id == ID_KICK);
    assign trig_snare = in_valid && (synth_id == ID_SNARE);
    assign trig_hihat = in_valid && (synth_id == ID_HIHAT);

    // Kick
    always_ff @(posedge clk) begin
        if (!rst_n) begin
            kick_ptr    <= '0;
            kick_active <= 1'b0;
        end else begin
            if (trig_kick) begin
                kick_ptr    <= '0;
                kick_active <= 1'b1;
            end else if (sample_en && kick_active) begin
                if (kick_ptr == KICK_LEN - 1) begin
                    kick_active <= 1'b0;
                    kick_ptr    <= '0;
                end else
                    kick_ptr <= kick_ptr + 1;
            end
        end
    end

    // Snare
    always_ff @(posedge clk) begin
        if (!rst_n) begin
            snare_ptr    <= '0;
            snare_active <= 1'b0;
        end else begin
            if (trig_snare) begin
                snare_ptr    <= '0;
                snare_active <= 1'b1;
            end else if (sample_en && snare_active) begin
                if (snare_ptr == SNARE_LEN - 1) begin
                    snare_active <= 1'b0;
                    snare_ptr    <= '0;
                end else
                    snare_ptr <= snare_ptr + 1;
            end
        end
    end

    // Hi-hat
    always_ff @(posedge clk) begin
        if (!rst_n) begin
            hihat_ptr    <= '0;
            hihat_active <= 1'b0;
        end else begin
            if (trig_hihat) begin
                hihat_ptr    <= '0;
                hihat_active <= 1'b1;
            end else if (sample_en && hihat_active) begin
                if (hihat_ptr == HIHAT_LEN - 1) begin
                    hihat_active <= 1'b0;
                    hihat_ptr    <= '0;
                end else
                    hihat_ptr <= hihat_ptr + 1;
            end
        end
    end

    // Mix: $signed() reinterprets the unsigned hex as two's complement
    logic signed [25:0] mix;
    always_comb begin
        mix = 26'sd0;
        if (kick_active)  mix = mix + 26'($signed(kick_lut[kick_ptr]));
        if (snare_active) mix = mix + 26'($signed(snare_lut[snare_ptr]));
        if (hihat_active) mix = mix + 26'($signed(hihat_lut[hihat_ptr]));
    end

    always_ff @(posedge clk) begin
        if (!rst_n)
            out_sample <= 24'sd0;
        else if (sample_en) begin
            if      (mix > 26'sd8388607)  out_sample <=  24'sd8388607;
            else if (mix < -26'sd8388608) out_sample <= -24'sd8388608;
            else                          out_sample <= $signed(mix[23:0]);
        end
    end

endmodule